using UnityEngine;
using UnityEngine.UI;
using UnityEditor;

public class FixCookingUIV2
{
    public static string Main()
    {
        var sb = new System.Text.StringBuilder();
        Font fontPoppins = AssetDatabase.LoadAssetAtPath<Font>("Assets/Font/Poppins-Light.ttf");

        Canvas mainCanvas = null;
        var canvases = Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None);
        foreach (var c in canvases)
        {
            if (c.transform.Find("PanelMemasak_Old") != null || c.transform.Find("PanelMemasakV2") != null)
            {
                mainCanvas = c;
                break;
            }
        }

        if (mainCanvas == null) return "ERROR: Canvas utama tidak ditemukan.";

        var existingV2 = mainCanvas.transform.Find("PanelMemasakV2");
        if (existingV2 != null) Object.DestroyImmediate(existingV2.gameObject);

        GameObject panelGO = new GameObject("PanelMemasakV2");
        panelGO.transform.SetParent(mainCanvas.transform, false);
        RectTransform panelRT = panelGO.AddComponent<RectTransform>();
        panelRT.anchorMin = Vector2.zero;
        panelRT.anchorMax = Vector2.one;
        panelRT.offsetMin = Vector2.zero;
        panelRT.offsetMax = Vector2.zero;

        Image bg = panelGO.AddComponent<Image>();
        bg.color = new Color(0.08f, 0.08f, 0.1f, 0.95f);

        CookingUI cookingUI = panelGO.AddComponent<CookingUI>();
        cookingUI.columns = 5;      // Grid 5x5
        cookingUI.visibleRows = 5;  // Grid 5x5
        cookingUI.spacingX = 0.02f;
        cookingUI.spacingY = 0.02f;

        // --- HEADER ---
        GameObject headerGO = new GameObject("HeaderTitle");
        headerGO.transform.SetParent(panelGO.transform, false);
        RectTransform headerRT = headerGO.AddComponent<RectTransform>();
        headerRT.anchorMin = new Vector2(0f, 0.9f);
        headerRT.anchorMax = new Vector2(1f, 1f);
        headerRT.offsetMin = Vector2.zero;
        headerRT.offsetMax = Vector2.zero;
        Text headerTxt = headerGO.AddComponent<Text>();
        headerTxt.text = "MEMASAK";
        headerTxt.font = fontPoppins;
        headerTxt.fontSize = 32;
        headerTxt.alignment = TextAnchor.MiddleCenter;
        headerTxt.color = new Color(0.9f, 0.85f, 0.7f);

        // --- LEFT PANEL (5x5 Area) ---
        GameObject leftGO = new GameObject("LeftPanel");
        leftGO.transform.SetParent(panelGO.transform, false);
        RectTransform leftRT = leftGO.AddComponent<RectTransform>();
        leftRT.anchorMin = new Vector2(0.02f, 0.05f);
        leftRT.anchorMax = new Vector2(0.48f, 0.88f); // Diperlebar agar muat 5 kolom
        leftRT.offsetMin = Vector2.zero;
        leftRT.offsetMax = Vector2.zero;
        Image leftBg = leftGO.AddComponent<Image>();
        leftBg.color = new Color(0f, 0f, 0f, 0.3f);

        // --- RIGHT PANEL ---
        GameObject rightGO = new GameObject("RightPanel");
        rightGO.transform.SetParent(panelGO.transform, false);
        RectTransform rightRT = rightGO.AddComponent<RectTransform>();
        rightRT.anchorMin = new Vector2(0.5f, 0.05f);
        rightRT.anchorMax = new Vector2(0.98f, 0.88f);
        rightRT.offsetMin = Vector2.zero;
        rightRT.offsetMax = Vector2.zero;
        Image rightBg = rightGO.AddComponent<Image>();
        rightBg.color = new Color(0.12f, 0.12f, 0.15f, 0.8f);

        // Detail: Food Image
        GameObject foodImgGO = new GameObject("FoodImage");
        foodImgGO.transform.SetParent(rightGO.transform, false);
        RectTransform foodImgRT = foodImgGO.AddComponent<RectTransform>();
        foodImgRT.anchorMin = new Vector2(0.25f, 0.5f);
        foodImgRT.anchorMax = new Vector2(0.75f, 0.95f);
        foodImgRT.offsetMin = Vector2.zero;
        foodImgRT.offsetMax = Vector2.zero;
        Image foodImg = foodImgGO.AddComponent<Image>();
        foodImg.preserveAspect = true;

        // Detail: Title
        GameObject titleGO = new GameObject("TxtRecipeName");
        titleGO.transform.SetParent(rightGO.transform, false);
        RectTransform titleRT = titleGO.AddComponent<RectTransform>();
        titleRT.anchorMin = new Vector2(0.05f, 0.4f);
        titleRT.anchorMax = new Vector2(0.95f, 0.5f);
        titleRT.offsetMin = Vector2.zero;
        titleRT.offsetMax = Vector2.zero;
        Text titleTxt = titleGO.AddComponent<Text>();
        titleTxt.font = fontPoppins;
        titleTxt.fontSize = 28;
        titleTxt.alignment = TextAnchor.MiddleCenter;
        titleTxt.color = Color.white;

        // Detail: Desc
        GameObject descGO = new GameObject("TxtRecipeDesc");
        descGO.transform.SetParent(rightGO.transform, false);
        RectTransform descRT = descGO.AddComponent<RectTransform>();
        descRT.anchorMin = new Vector2(0.05f, 0.3f);
        descRT.anchorMax = new Vector2(0.95f, 0.4f);
        descRT.offsetMin = Vector2.zero;
        descRT.offsetMax = Vector2.zero;
        Text descTxt = descGO.AddComponent<Text>();
        descTxt.font = fontPoppins;
        descTxt.fontSize = 16;
        descTxt.alignment = TextAnchor.UpperCenter;
        descTxt.color = new Color(0.8f, 0.8f, 0.8f);

        // Detail: HP Restore
        GameObject hpGO = new GameObject("TxtHPRestore");
        hpGO.transform.SetParent(rightGO.transform, false);
        RectTransform hpRT = hpGO.AddComponent<RectTransform>();
        hpRT.anchorMin = new Vector2(0.05f, 0.25f);
        hpRT.anchorMax = new Vector2(0.95f, 0.3f);
        hpRT.offsetMin = Vector2.zero;
        hpRT.offsetMax = Vector2.zero;
        Text hpTxt = hpGO.AddComponent<Text>();
        hpTxt.font = fontPoppins;
        hpTxt.fontSize = 16;
        hpTxt.alignment = TextAnchor.MiddleCenter;
        hpTxt.color = new Color(0.5f, 0.9f, 0.5f);

        // --- INGREDIENTS CONTAINER ---
        GameObject ingContainer = new GameObject("IngredientsArea");
        ingContainer.transform.SetParent(rightGO.transform, false);
        RectTransform ingRT = ingContainer.AddComponent<RectTransform>();
        ingRT.anchorMin = new Vector2(0.02f, 0.02f);
        ingRT.anchorMax = new Vector2(0.7f, 0.23f);
        ingRT.offsetMin = Vector2.zero;
        ingRT.offsetMax = Vector2.zero;

        HorizontalLayoutGroup hlg = ingContainer.AddComponent<HorizontalLayoutGroup>();
        hlg.childAlignment = TextAnchor.MiddleLeft;
        hlg.childControlHeight = true;
        hlg.childControlWidth = true;
        hlg.childForceExpandHeight = true;
        hlg.childForceExpandWidth = true;
        hlg.spacing = 10f;

        var slots = new System.Collections.Generic.List<GameObject>();
        var icons = new System.Collections.Generic.List<Image>();
        var names = new System.Collections.Generic.List<Text>();
        var amounts = new System.Collections.Generic.List<Text>();

        for (int i = 0; i < 4; i++)
        {
            GameObject slotGO = new GameObject("IngredientSlot_" + i);
            slotGO.transform.SetParent(ingContainer.transform, false);

            Image slotBg = slotGO.AddComponent<Image>();
            slotBg.color = new Color(0.2f, 0.2f, 0.2f, 0.5f);

            GameObject iconGO = new GameObject("Icon");
            iconGO.transform.SetParent(slotGO.transform, false);
            RectTransform iconRT = iconGO.AddComponent<RectTransform>();
            iconRT.anchorMin = new Vector2(0.2f, 0.4f);
            iconRT.anchorMax = new Vector2(0.8f, 0.9f);
            iconRT.offsetMin = Vector2.zero;
            iconRT.offsetMax = Vector2.zero;
            Image iconImg = iconGO.AddComponent<Image>();
            iconImg.preserveAspect = true;

            GameObject nameGO = new GameObject("Name");
            nameGO.transform.SetParent(slotGO.transform, false);
            RectTransform nameRT = nameGO.AddComponent<RectTransform>();
            nameRT.anchorMin = new Vector2(0f, 0.2f);
            nameRT.anchorMax = new Vector2(1f, 0.4f);
            nameRT.offsetMin = Vector2.zero;
            nameRT.offsetMax = Vector2.zero;
            Text nameTxt = nameGO.AddComponent<Text>();
            nameTxt.font = fontPoppins;
            nameTxt.fontSize = 14;
            nameTxt.alignment = TextAnchor.MiddleCenter;
            nameTxt.color = Color.white;
            nameTxt.resizeTextForBestFit = true;
            nameTxt.resizeTextMaxSize = 14;
            nameTxt.resizeTextMinSize = 8;

            GameObject amtGO = new GameObject("Amount");
            amtGO.transform.SetParent(slotGO.transform, false);
            RectTransform amtRT = amtGO.AddComponent<RectTransform>();
            amtRT.anchorMin = new Vector2(0f, 0f);
            amtRT.anchorMax = new Vector2(1f, 0.2f);
            amtRT.offsetMin = Vector2.zero;
            amtRT.offsetMax = Vector2.zero;
            Text amtTxt = amtGO.AddComponent<Text>();
            amtTxt.font = fontPoppins;
            amtTxt.fontSize = 14;
            amtTxt.alignment = TextAnchor.MiddleCenter;
            amtTxt.color = Color.white;
            amtTxt.resizeTextForBestFit = true;

            slots.Add(slotGO);
            icons.Add(iconImg);
            names.Add(nameTxt);
            amounts.Add(amtTxt);
        }

        // --- COOK BUTTON ---
        GameObject btnMasakGO = new GameObject("BtnMasak");
        btnMasakGO.transform.SetParent(rightGO.transform, false);
        RectTransform btnMasakRT = btnMasakGO.AddComponent<RectTransform>();
        btnMasakRT.anchorMin = new Vector2(0.72f, 0.05f);
        btnMasakRT.anchorMax = new Vector2(0.95f, 0.2f);
        btnMasakRT.offsetMin = Vector2.zero;
        btnMasakRT.offsetMax = Vector2.zero;
        Image btnMasakImg = btnMasakGO.AddComponent<Image>();
        btnMasakImg.color = new Color(0.85f, 0.65f, 0.2f);
        Button btnMasak = btnMasakGO.AddComponent<Button>();
        btnMasak.targetGraphic = btnMasakImg;

        GameObject btnMasakTxtGO = new GameObject("Text");
        btnMasakTxtGO.transform.SetParent(btnMasakGO.transform, false);
        RectTransform btnMasakTxtRT = btnMasakTxtGO.AddComponent<RectTransform>();
        btnMasakTxtRT.anchorMin = Vector2.zero;
        btnMasakTxtRT.anchorMax = Vector2.one;
        btnMasakTxtRT.offsetMin = Vector2.zero;
        btnMasakTxtRT.offsetMax = Vector2.zero;
        Text btnMasakTxt = btnMasakTxtGO.AddComponent<Text>();
        btnMasakTxt.text = "MASAK";
        btnMasakTxt.font = fontPoppins;
        btnMasakTxt.fontSize = 24;
        btnMasakTxt.alignment = TextAnchor.MiddleCenter;
        btnMasakTxt.color = Color.white;

        // --- CLOSE BUTTON ---
        GameObject btnCloseGO = new GameObject("BtnClose");
        btnCloseGO.transform.SetParent(panelGO.transform, false);
        RectTransform btnCloseRT = btnCloseGO.AddComponent<RectTransform>();
        btnCloseRT.anchorMin = new Vector2(0.92f, 0.92f);
        btnCloseRT.anchorMax = new Vector2(0.98f, 0.98f);
        btnCloseRT.offsetMin = Vector2.zero;
        btnCloseRT.offsetMax = Vector2.zero;
        Image btnCloseImg = btnCloseGO.AddComponent<Image>();
        btnCloseImg.color = new Color(0.3f, 0.3f, 0.3f);
        Button btnClose = btnCloseGO.AddComponent<Button>();
        btnClose.targetGraphic = btnCloseImg;
        GameObject btnCloseTxtGO = new GameObject("Text");
        btnCloseTxtGO.transform.SetParent(btnCloseGO.transform, false);
        RectTransform btnCloseTxtRT = btnCloseTxtGO.AddComponent<RectTransform>();
        btnCloseTxtRT.anchorMin = Vector2.zero;
        btnCloseTxtRT.anchorMax = Vector2.one;
        btnCloseTxtRT.offsetMin = Vector2.zero;
        btnCloseTxtRT.offsetMax = Vector2.zero;
        Text btnCloseTxt = btnCloseTxtGO.AddComponent<Text>();
        btnCloseTxt.text = "X";
        btnCloseTxt.font = fontPoppins;
        btnCloseTxt.fontSize = 24;
        btnCloseTxt.alignment = TextAnchor.MiddleCenter;
        btnCloseTxt.color = Color.white;

        // --- STATUS MESSAGE ---
        GameObject statusGO = new GameObject("TxtStatusMessage");
        statusGO.transform.SetParent(panelGO.transform, false);
        RectTransform statusRT = statusGO.AddComponent<RectTransform>();
        statusRT.anchorMin = new Vector2(0.2f, 0.01f);
        statusRT.anchorMax = new Vector2(0.8f, 0.06f);
        statusRT.offsetMin = Vector2.zero;
        statusRT.offsetMax = Vector2.zero;
        Text statusTxt = statusGO.AddComponent<Text>();
        statusTxt.font = fontPoppins;
        statusTxt.fontSize = 18;
        statusTxt.alignment = TextAnchor.MiddleCenter;
        statusTxt.color = Color.white;

        // --- WIRE COOKINGUI ---
        cookingUI.leftPanel = leftRT;
        cookingUI.recipeName = titleTxt;
        cookingUI.recipeDescription = descTxt;
        cookingUI.recipeImage = foodImg;
        cookingUI.hpRestoreText = hpTxt;
        cookingUI.statusMessage = statusTxt;
        cookingUI.cookButton = btnMasak;
        cookingUI.closeButton = btnClose;

        cookingUI.ingredientSlots = slots.ToArray();
        cookingUI.ingredientIcons = icons.ToArray();
        cookingUI.ingredientNames = names.ToArray();
        cookingUI.ingredientAmounts = amounts.ToArray();

        // Assign Recipes
        string recipeFolder = "Assets/Herbal/Recipes";
        string[] recipeNames = { "Jamu Jahe", "Jamu Kunyit", "Jamu Kencur", "Jamu Temulawak", "Wedang Jahe", "Jamu Beras Kencur" };
        var recipes = new System.Collections.Generic.List<CookingRecipe>();
        foreach (var rn in recipeNames)
        {
            var recipe = AssetDatabase.LoadAssetAtPath<CookingRecipe>(recipeFolder + "/" + rn + ".asset");
            if (recipe != null) recipes.Add(recipe);
        }
        cookingUI.recipes = recipes.ToArray();

        // --- GENERATE SIMPLE ASSET ICONS ---
        // Generate placeholder sprites programmatically if needed
        Texture2D texDrink = new Texture2D(64, 64);
        Texture2D texRoot = new Texture2D(64, 64);
        for(int x=0;x<64;x++) for(int y=0;y<64;y++) {
            texDrink.SetPixel(x,y, new Color(0.8f, 0.6f, 0.2f, (x*y>1000)?1f:0.5f));
            texRoot.SetPixel(x,y, new Color(0.6f, 0.4f, 0.2f, (x+y>64)?1f:0.5f));
        }
        texDrink.Apply(); texRoot.Apply();
        byte[] bytesDrink = texDrink.EncodeToPNG();
        byte[] bytesRoot = texRoot.EncodeToPNG();

        string pathDrink = "Assets/Herbal/DrinkIcon.png";
        string pathRoot = "Assets/Herbal/RootIcon.png";
        if (!System.IO.File.Exists(pathDrink)) System.IO.File.WriteAllBytes(pathDrink, bytesDrink);
        if (!System.IO.File.Exists(pathRoot)) System.IO.File.WriteAllBytes(pathRoot, bytesRoot);
        AssetDatabase.Refresh();

        // Set texture import settings to Sprite
        TextureImporter tiDrink = (TextureImporter)AssetImporter.GetAtPath(pathDrink);
        if (tiDrink != null) { tiDrink.textureType = TextureImporterType.Sprite; tiDrink.SaveAndReimport(); }
        TextureImporter tiRoot = (TextureImporter)AssetImporter.GetAtPath(pathRoot);
        if (tiRoot != null) { tiRoot.textureType = TextureImporterType.Sprite; tiRoot.SaveAndReimport(); }

        Sprite spDrink = AssetDatabase.LoadAssetAtPath<Sprite>(pathDrink);
        Sprite spRoot = AssetDatabase.LoadAssetAtPath<Sprite>(pathRoot);

        // Assign to recipes
        foreach (var r in recipes)
        {
            r.recipeImage = spDrink;
            foreach(var ing in r.ingredients) {
                ing.itemIcon = spRoot;
            }
            EditorUtility.SetDirty(r);
        }

        // Assign to Result Items
        string itemFolder = "Assets/Herbal/Items";
        foreach (var rn in recipeNames)
        {
            var item = AssetDatabase.LoadAssetAtPath<InventoryItem>(itemFolder + "/" + rn + ".asset");
            if (item != null) {
                item.icon = spDrink;
                EditorUtility.SetDirty(item);
            }
        }

        // Assign to Ingredients
        string[] ingNames = { "Jahe", "Kunyit", "Kencur", "Temulawak", "Kayu Manis" };
        foreach (var iName in ingNames)
        {
            var item = AssetDatabase.LoadAssetAtPath<InventoryItem>(itemFolder + "/" + iName + ".asset");
            if (item != null) {
                item.icon = spRoot;
                EditorUtility.SetDirty(item);
            }
        }
        AssetDatabase.SaveAssets();

        // --- UPDATE TRIGGER ---
        var masakGO = GameObject.Find("Masak");
        if (masakGO != null)
        {
            var trigger = masakGO.GetComponent<CookingTrigger>();
            if (trigger != null)
            {
                trigger.cookingCanvas = panelGO;
                cookingUI.cookingTrigger = trigger;
                sb.AppendLine("[OK] Trigger diupdate ke PanelMemasakV2");
            }
        }

        panelGO.SetActive(false);
        sb.AppendLine("[OK] Fix PanelMemasakV2 berhasil dibuat dan icon digenerate");

        UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());
        return sb.ToString();
    }
}
